    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [[background for _ in range(w)] for _ in range(h)]

    # Rectangular fields have no background-colored holes: sparse marks of any
    # other color may interrupt them. Find dense, all-non-background boxes.
    for color in {v for row in grid for v in row if v != background}:
        pref_color = [[0] * (w + 1) for _ in range(h + 1)]
        pref_bg = [[0] * (w + 1) for _ in range(h + 1)]
        for r in range(h):
            for c in range(w):
                pref_color[r + 1][c + 1] = (
                    pref_color[r][c + 1] + pref_color[r + 1][c]
                    - pref_color[r][c] + (grid[r][c] == color)
                )
                pref_bg[r + 1][c + 1] = (
                    pref_bg[r][c + 1] + pref_bg[r + 1][c]
